export type AiProviderId = typeof aiProviders[number]['id'];
export interface AiConnection {
  provider: AiProviderId;
  baseUrl: string;
  model: string;
  apiKey: string;
}
export interface AiPreferences {
  provider: AiProviderId;
  connections: Partial<Record<AiProviderId, AiConnection>>;
}
export const AI_CONNECTIONS_KEY = 'qwertophone.effects-ai-connections.v1';

export const defaultAiConnection = (id: AiProviderId): AiConnection => {
  const provider = aiProviders.find(item => item.id === id)!;
  return {
    provider: id,
    baseUrl: provider.baseUrl,
    model: provider.model,
    apiKey: '',
  };
};

export const loadAiPreferences = (): AiPreferences => {
  const fallback: AiPreferences = { provider: 'openrouter', connections: {} };
  try {
    const saved = JSON.parse(
      localStorage.getItem(AI_CONNECTIONS_KEY) ?? 'null',
    );
    if (saved?.version !== 1) return fallback;
    const connections: AiPreferences['connections'] = {};
    aiProviders.forEach(provider => {
      const value = saved.connections?.[provider.id];
      if (!value || typeof value !== 'object') return;
      connections[provider.id] = {
        ...defaultAiConnection(provider.id),
        apiKey: typeof value.apiKey === 'string' ? value.apiKey : '',
        model:
          typeof value.model === 'string'
            ? value.model.slice(0, 200)
            : provider.model,
        // Fixed providers always use their documented endpoint.
        baseUrl:
          provider.id === 'custom' && typeof value.baseUrl === 'string'
            ? value.baseUrl.slice(0, 500)
            : provider.baseUrl,
      };
    });
    return {
      provider: aiProviders.some(item => item.id === saved.provider)
        ? saved.provider
        : fallback.provider,
      connections,
    };
  } catch {
    return fallback;
  }
};

export const saveAiPreferences = (value: AiPreferences): boolean => {
  try {
    localStorage.setItem(
      AI_CONNECTIONS_KEY,
      JSON.stringify({ version: 1, ...value }),
    );
    return true;
  } catch {
    return false;
  }
};

export const aiBaseUrl = (connection: AiConnection): string => {
  const provider = aiProviders.find(item => item.id === connection.provider);
  const value =
    provider?.id === 'custom' ? connection.baseUrl : provider?.baseUrl;
  try {
    const url = new URL(value?.trim() ?? '');
    const local = ['localhost', '127.0.0.1', '[::1]'].includes(url.hostname);
    if (
      (url.protocol !== 'https:' && !(local && url.protocol === 'http:')) ||
      url.username ||
      url.password ||
      url.search ||
      url.hash
    )
      throw new Error();
    return url.href.replace(/\/+$/, '');
  } catch {
    throw new Error(
      'Enter an HTTPS API URL without keys or query parameters. HTTP is allowed for localhost.',
    );
  }
};

export const requestAi = async (
  connection: AiConnection,
  path: string,
  signal: AbortSignal,
  body?: unknown,
): Promise<unknown> => {
  const baseUrl = aiBaseUrl(connection);
  if (!connection.apiKey.trim() && connection.provider !== 'custom')
    throw new Error("Enter the selected provider's API key in AI settings.");
  const response = await fetch(`${baseUrl}/${path}`, {
    method: body === undefined ? 'GET' : 'POST',
    headers: {
      ...(body === undefined ? {} : { 'Content-Type': 'application/json' }),
      ...(connection.apiKey.trim()
        ? { Authorization: `Bearer ${connection.apiKey.trim()}` }
        : {}),
    },
    ...(body === undefined ? {} : { body: JSON.stringify(body) }),
    signal,
    credentials: 'omit',
    referrerPolicy: 'no-referrer',
    redirect: 'error',
  });
  if (!response.ok) {
    const messages: Record<number, string> = {
      400: 'This model does not support the request. Choose another text model.',
      401: "API key rejected. Check the selected provider's key.",
      402: 'Insufficient funds with the AI provider.',
      403: 'Access denied. Check key permissions and provider availability.',
      404: 'Model or API URL not found. Refresh the model list.',
      429: 'Rate limit or quota exceeded. Try later or check your balance.',
    };
    // Never surface raw provider errors: they can echo request credentials.
    throw new Error(
      messages[response.status] ??
        'The AI provider is temporarily unavailable. Try again.',
    );
  }
  return response.json();
};

export const loadAiModels = async (
  connection: AiConnection,
  signal: AbortSignal,
): Promise<string[]> => {
  const result = (await requestAi(connection, 'models', signal)) as {
    data?: unknown;
  };
  if (!Array.isArray(result?.data))
    throw new Error(
      'The service did not return a model list. Enter a model ID manually.',
    );
  const ids = result.data
    .filter(
      item =>
        typeof item?.id === 'string' &&
        item.id.length <= 200 &&
        (!Array.isArray(item.architecture?.output_modalities) ||
          item.architecture.output_modalities.includes('text')) &&
        !/embedding|whisper|tts|dall-e|moderation|transcrib|realtime|image|audio|sora/i.test(
          item.id,
        ),
    )
    .map(item => item.id as string);
  return Array.from(new Set(ids)).sort();
};
