import { InstrumentEffects } from 'app/services/EffectsService/settings';
import { prepareInstrumentSample } from 'app/services/SynthesizerService';
import { Timbre } from 'app/services/SynthesizerService/types';

import { GuitarCapture } from './capture';
import {
  LiveTranscription,
  createLiveTranscription,
} from './liveTranscription';
import { createInputTimbrePlayer } from './timbrePlayer';

export type TimbreMonitor = {
  ready: Promise<void>;
  dispose(): void;
  updateEffects(settings: InstrumentEffects): void;
  level(): { rms: number; peak: number };
  setAmount?(amount: number): void;
};

export const createTimbreMonitor = (
  input: GuitarCapture,
  timbre: Timbre,
  settings: InstrumentEffects,
  polyphonic: boolean,
  onError: (error: Error) => void,
): TimbreMonitor => {
  let disposed = false;
  let recognition: LiveTranscription | undefined;
  let player: ReturnType<typeof createInputTimbrePlayer> | undefined;
  const dispose = () => {
    if (disposed) return;
    disposed = true;
    input.setSampleListener();
    recognition?.dispose();
    player?.dispose();
  };
  const ready = prepareInstrumentSample(timbre).then(buffer => {
    if (disposed) return;
    player = createInputTimbrePlayer(
      input.audioContext,
      buffer,
      timbre,
      settings,
    );
    recognition = createLiveTranscription(
      frame => {
        if (!disposed) player?.update(frame);
      },
      error => {
        if (disposed) return;
        dispose();
        onError(error);
      },
      !polyphonic,
      undefined,
      true,
    );
    input.setSampleListener(recognition.push);
  });
  return {
    ready,
    dispose,
    updateEffects(value: InstrumentEffects) {
      settings = value;
      player?.updateEffects(value);
    },
    level: () => player?.level() ?? { rms: 0, peak: 0 },
  };
};
