import { useCallback, useEffect, useRef, useState } from 'react';

import type { JustNote } from 'app/services/NotesService/types';
import {
  loadSound,
  playLiveExpressiveNote,
  resumeAudio,
} from 'app/services/SynthesizerService';

import type { ScalePreviewNote } from './scalePreview';

const piano = 'studioResonantPiano';
const noteDuration = 330;

export const useScalePreview = () => {
  const run = useRef<{ timer?: number; release?: () => void }>();
  const [activeKey, setActiveKey] = useState<JustNote>();
  const [isPlaying, setPlaying] = useState(false);
  const [failed, setFailed] = useState(false);

  const clear = useCallback(() => {
    const current = run.current;
    run.current = undefined;
    window.clearTimeout(current?.timer);
    current?.release?.();
  }, []);

  const stop = useCallback(() => {
    clear();
    setPlaying(false);
    setActiveKey(undefined);
    setFailed(false);
  }, [clear]);

  const play = async (notes: ScalePreviewNote[]) => {
    stop();
    const current: NonNullable<typeof run.current> = {};
    run.current = current;
    setPlaying(true);

    const fail = () => {
      stop();
      setFailed(true);
    };

    const advance = (index: number) => {
      current.release?.();
      current.release = undefined;
      const next = notes[index];
      if (!next) {
        stop();
        return;
      }
      const voice = playLiveExpressiveNote(piano, next.note);
      if (!voice) {
        fail();
        return;
      }
      if (next.cents) voice.setPitchOffset(next.cents, 'step');
      current.release = voice.stop;
      setActiveKey(next.key);
      current.timer = window.setTimeout(() => advance(index + 1), noteDuration);
    };

    try {
      await Promise.all([resumeAudio(), loadSound(piano)]);
      if (run.current === current) advance(0);
    } catch {
      if (run.current === current) fail();
    }
  };

  useEffect(() => {
    const onVisibilityChange = () => {
      if (document.hidden) stop();
    };
    window.addEventListener('blur', stop);
    document.addEventListener('visibilitychange', onVisibilityChange);
    return () => {
      clear();
      window.removeEventListener('blur', stop);
      document.removeEventListener('visibilitychange', onVisibilityChange);
    };
  }, [clear, stop]);

  return { play, stop, activeKey, isPlaying, failed };
};
