import {
  EffectStage,
  InstrumentEffects,
  MAX_PEDALS,
  MAX_PEDAL_STAGES,
  effectDefinitions,
  effectNames,
  normalizeEffects,
  toEffectStage,
} from './settings';

export interface EffectPreset {
  id: string;
  name: string;
  description?: string;
  settings: InstrumentEffects;
  category?: string;
  tags?: string[];
}

export { builtInEffectPresets, effectPresetCategories } from './presetCatalog';

// Presets describe the pedals. The destination keeps its own output level.
export const applyEffectPreset = (
  selected: EffectPreset,
  current: InstrumentEffects,
): InstrumentEffects => ({
  ...normalizeEffects('', selected.settings),
  volume: current.volume,
  bypass: false,
});

export const matchesEffectPreset = (
  selected: EffectPreset,
  current: InstrumentEffects,
) =>
  (selected.settings.wahMode ?? 'auto') === (current.wahMode ?? 'auto') &&
  JSON.stringify(selected.settings.pedals ?? []) ===
    JSON.stringify(current.pedals ?? []) &&
  effectNames.every(name => {
    const expected = selected.settings[name];
    const actual = current[name];
    return (
      expected.enabled === actual.enabled &&
      effectDefinitions[name].controls.every(
        ({ key }) =>
          (expected as unknown as Record<string, number>)[key] ===
          (actual as unknown as Record<string, number>)[key],
      )
    );
  });

export const EFFECT_PRESETS_STORAGE_KEY = 'qwertophone.effect-presets.v1';

export const normalizePresetName = (name: string) => name.trim().slice(0, 60);

export const loadEffectPresets = (): EffectPreset[] => {
  try {
    const saved = JSON.parse(
      localStorage.getItem(EFFECT_PRESETS_STORAGE_KEY) ?? 'null',
    );
    if (saved?.version !== 1 || !Array.isArray(saved.presets)) return [];
    const result: EffectPreset[] = [];
    for (const value of saved.presets) {
      if (
        !value ||
        typeof value.id !== 'string' ||
        !value.id.startsWith('custom-') ||
        typeof value.name !== 'string' ||
        !normalizePresetName(value.name) ||
        !value.settings ||
        typeof value.settings !== 'object' ||
        Array.isArray(value.settings) ||
        result.some(item => item.id === value.id)
      )
        continue;
      result.push({
        id: value.id,
        name: normalizePresetName(value.name),
        settings: {
          ...normalizeEffects('', value.settings),
          volume: 100,
          bypass: false,
        },
      });
    }
    return result;
  } catch {
    return [];
  }
};

export const saveEffectPresets = (presets: EffectPreset[]): boolean => {
  try {
    localStorage.setItem(
      EFFECT_PRESETS_STORAGE_KEY,
      JSON.stringify({ version: 1, presets }),
    );
    return true;
  } catch {
    return false;
  }
};

const searchText = (value: string) =>
  value.toLocaleLowerCase().replace(/ё/g, 'е');

export const filterEffectPresets = (
  presets: EffectPreset[],
  query: string,
  category = 'all',
) => {
  const words = searchText(query).trim().split(/\s+/).filter(Boolean);
  return presets.filter(
    item =>
      (category === 'all' ||
        (category === 'custom'
          ? item.id.startsWith('custom-')
          : item.category === category)) &&
      words.every(word =>
        searchText(
          [
            item.id.replace(/-/g, ' '),
            item.name,
            item.description,
            ...(item.tags ?? []),
          ].join(' '),
        ).includes(word),
      ),
  );
};

export const presetStages = (preset: EffectPreset): EffectStage[] => {
  const settings = normalizeEffects('', preset.settings);
  const initial = toEffectStage(settings);
  const stages = [
    initial.wah.enabled ? { ...initial, wahMode: settings.wahMode } : initial,
    ...(settings.pedals ?? [])
      .filter(pedal => pedal.enabled)
      .flatMap(pedal =>
        pedal.stages.map(stage =>
          stage.wah.enabled
            ? { ...stage, wahMode: stage.wahMode ?? settings.wahMode }
            : stage,
        ),
      ),
  ];
  const active = stages.filter(stage =>
    effectNames.some(name => stage[name].enabled),
  );
  return active.length ? active : [initial];
};

export const canAddPresetPedal = (
  settings: InstrumentEffects,
  preset: EffectPreset,
) =>
  (settings.pedals?.length ?? 0) < MAX_PEDALS &&
  (settings.pedals ?? []).reduce(
    (count, pedal) => count + pedal.stages.length,
    0,
  ) +
    presetStages(preset).length <=
    MAX_PEDAL_STAGES;

export const togglePresetPedal = (
  settings: InstrumentEffects,
  preset: EffectPreset,
): InstrumentEffects => {
  const pedals = settings.pedals ?? [];
  const existing = pedals.find(pedal => pedal.presetId === preset.id);
  if (existing)
    return {
      ...settings,
      pedals: pedals.map(pedal =>
        pedal.id === existing.id
          ? { ...pedal, enabled: !pedal.enabled }
          : pedal,
      ),
    };
  if (!canAddPresetPedal(settings, preset)) return settings;
  return {
    ...settings,
    bypass: false,
    pedals: [
      ...pedals,
      {
        id: `pedal-${Date.now().toString(36)}-${Math.random()
          .toString(36)
          .slice(2, 8)}`,
        presetId: preset.id,
        name: preset.name,
        enabled: true,
        stages: presetStages(preset),
      },
    ],
  };
};
