import {
  InstrumentEffects,
  normalizeEffects,
} from 'app/services/EffectsService/settings';
import {
  TimeSignature,
  getTimeSignature,
} from 'app/services/MelodiesService/meter';
import { clampTempo } from 'app/services/MelodiesService/tempo';

import { DrumMachineState, normalizeDrumState } from './patterns';

export interface DrumBeat {
  state: DrumMachineState;
  bpm: number;
  timeSignature: TimeSignature;
  effects: InstrumentEffects;
}

export interface SavedDrumBeat extends DrumBeat {
  id: string;
  name: string;
}

export const MAX_BEAT_NAME_LENGTH = 60;
const storageKey = 'qwertophone.drum-beats.v1';

export const loadSavedDrumBeats = (): SavedDrumBeat[] => {
  try {
    const saved = JSON.parse(localStorage.getItem(storageKey) ?? '[]');
    if (!Array.isArray(saved)) return [];
    return saved.flatMap((beat: Partial<SavedDrumBeat> | null) => {
      if (
        !beat ||
        typeof beat.id !== 'string' ||
        !beat.id ||
        typeof beat.name !== 'string' ||
        !beat.name.trim() ||
        !Array.isArray(beat.state?.tracks) ||
        typeof beat.bpm !== 'number' ||
        !Number.isFinite(beat.bpm)
      )
        return [];
      return [
        {
          id: beat.id,
          name: beat.name.trim().slice(0, MAX_BEAT_NAME_LENGTH),
          state: normalizeDrumState(beat.state),
          bpm: clampTempo(beat.bpm),
          timeSignature: getTimeSignature(beat.timeSignature),
          effects: normalizeEffects('drums', beat.effects),
        },
      ];
    });
  } catch {
    return [];
  }
};

export const writeSavedDrumBeats = (beats: SavedDrumBeat[]) => {
  localStorage.setItem(storageKey, JSON.stringify(beats));
};
