import { useSelector } from 'react-redux';
import styled from 'styled-components';

import { selectLoading } from 'app/services/CommonService';

import { LoadingIndicator } from './LoadingIndicator';

export const Loader = () => {
  const isLoading = useSelector(selectLoading);
  if (!isLoading) {
    return null;
  }
  return (
    <LoadingBackground>
      <LoadingIndicator />
    </LoadingBackground>
  );
};

const LoadingBackground = styled.div`
  position: fixed;
  left: 0;
  top: 0;
  background-color: ${p => p.theme.overlay};
  width: 100vw;
  height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 9999;
  cursor: wait;
`;
