export const tunings = {
  standard: {
    label: 'Guitar: Standard',
    notes: ['E2', 'A2', 'D3', 'G3', 'B3', 'E4'],
  },
  dropD: {
    label: 'Guitar: Drop D',
    notes: ['D2', 'A2', 'D3', 'G3', 'B3', 'E4'],
  },
  bass: { label: 'Bass guitar: Standard', notes: ['E1', 'A1', 'D2', 'G2'] },
  ukulele: { label: 'Ukulele: Standard', notes: ['G4', 'C4', 'E4', 'A4'] },
} as const;

export type Tuning = keyof typeof tunings;
const noteNames = [
  'C',
  'C♯',
  'D',
  'D♯',
  'E',
  'F',
  'F♯',
  'G',
  'G♯',
  'A',
  'A♯',
  'B',
];

export const noteFrequency = (note: string) => {
  const pitch = noteNames.indexOf(note.slice(0, -1));
  const midi = (Number(note.slice(-1)) + 1) * 12 + pitch;
  return 440 * Math.pow(2, (midi - 69) / 12);
};

export const centsBetween = (frequency: number, target: number) =>
  1200 * Math.log2(frequency / target);

export const nearestNote = (frequency: number) => {
  const midi = Math.round(69 + 12 * Math.log2(frequency / 440));
  return `${noteNames[((midi % 12) + 12) % 12]}${Math.floor(midi / 12) - 1}`;
};

export const nearestString = (frequency: number, tuning: Tuning) => {
  const notes = tunings[tuning].notes;
  let best = 0;
  notes.forEach((note, index) => {
    if (
      Math.abs(centsBetween(frequency, noteFrequency(note))) <
      Math.abs(centsBetween(frequency, noteFrequency(notes[best])))
    )
      best = index;
  });
  return best;
};

// YIN: cumulative mean normalized difference, first reliable period and
// parabolic interpolation. See docs/TUNER.md for the original paper.
export const detectPitch = (
  input: Float32Array,
  sampleRate: number,
  maxFrequency = 500,
  minFrequency = 55,
) => {
  if (!Number.isFinite(sampleRate) || sampleRate <= 0 || input.length < 256)
    return null;
  // Average groups before decimation to keep the live analysis inexpensive.
  const stride = Math.max(1, Math.floor(sampleRate / 12000));
  const samples = new Float32Array(Math.floor(input.length / stride));
  let mean = 0;
  for (let i = 0; i < samples.length; i++) {
    let sum = 0;
    for (let j = 0; j < stride; j++) sum += input[i * stride + j];
    samples[i] = sum / stride;
    mean += samples[i];
  }
  mean /= samples.length;
  let energy = 0;
  for (let i = 0; i < samples.length; i++) {
    samples[i] -= mean;
    energy += samples[i] * samples[i];
  }
  if (Math.sqrt(energy / samples.length) < 0.008) return null;
  const rate = sampleRate / stride;
  const size = Math.floor(samples.length / 2);
  const minLag = Math.floor(rate / maxFrequency);
  const maxLag = Math.min(Math.ceil(rate / minFrequency), size - 1);
  const difference = new Float32Array(maxLag + 1);
  let cumulative = 0;
  for (let lag = 1; lag <= maxLag; lag++) {
    let sum = 0;
    for (let i = 0; i < size; i++) {
      const delta = samples[i] - samples[i + lag];
      sum += delta * delta;
    }
    cumulative += sum;
    difference[lag] = cumulative > 0 ? (sum * lag) / cumulative : 1;
  }
  for (let lag = Math.max(2, minLag); lag < maxLag; lag++) {
    if (difference[lag] >= 0.15) continue;
    while (lag + 1 < maxLag && difference[lag + 1] < difference[lag]) lag++;
    const left = difference[lag - 1];
    const center = difference[lag];
    const right = difference[lag + 1];
    const denominator = left - 2 * center + right;
    const offset = denominator ? (left - right) / (2 * denominator) : 0;
    const frequency = rate / (lag + Math.max(-1, Math.min(1, offset)));
    return frequency >= minFrequency && frequency <= maxFrequency
      ? frequency
      : null;
  }
  return null;
};
