import { Midi } from '@tonejs/midi';
import { MidiEvent, parseMidi, writeMidi } from 'midi-file';

import type {
  Melody,
  PlaybackMelody,
} from 'app/services/MelodiesService/types';
import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import { getNote } from 'app/services/NotesService/noteUtils';
import type { RecordingProject } from 'app/services/NotesService/slice/types';
import type { Octave } from 'app/services/NotesService/types';
import {
  isMicrotonalScale,
  noteTuningCents,
} from 'app/services/SettingsService/microtonal';

import type { Phrase } from './compose';
import { STEPS_PER_BEAT, timbrePrograms } from './options';

const title = 'Generated melody';
const bassTimbre = 'Deep Acoustic Bass Finger Fander';
const noteForMidi = (midi: number) =>
  getNote(chromaticNotes[midi % 12], (Math.floor(midi / 12) - 1) as Octave);

const phraseParts = (phrase: Phrase) =>
  [
    {
      id: 'melody',
      name: 'Melody',
      notes: phrase.melody,
      timbre: phrase.timbre,
      octave: 4,
      channel: 0,
      velocity: 0.8,
    },
    {
      id: 'accompaniment',
      name: 'Accompaniment',
      notes: phrase.accompaniment,
      timbre: phrase.timbre,
      octave: 2,
      channel: 1,
      velocity: 0.58,
    },
    {
      id: 'bass',
      name: 'Bass',
      notes: phrase.bassNotes,
      timbre: bassTimbre,
      octave: 1,
      channel: 2,
      velocity: 0.65,
    },
    {
      id: 'drums',
      name: 'Drums',
      notes: phrase.drumNotes,
      timbre: 'drums',
      octave: 3,
      channel: 9,
      velocity: 0.68,
    },
  ] as const;

export const phraseFilename = (
  phrase: Phrase,
  timbreLabel: string,
  format: 'midi' | 'wav' | 'mp3',
) => {
  const stem = [
    phrase.tonic,
    phrase.scale,
    phrase.mode,
    `${phrase.bpm}bpm`,
    phrase.timeSignature,
    `${phrase.bars}bars`,
    `chords-${phrase.chordPattern}`,
    phrase.bass && 'bass',
    phrase.drums && 'drums',
    timbreLabel,
    phrase.rhythm,
    phrase.mood,
    ...(phrase.customScale ?? []),
  ]
    .filter(Boolean)
    .join('-')
    .toLowerCase()
    .replace(/[^a-z0-9#]+/g, '-')
    .slice(0, 235)
    .replace(/-$/, '');
  return `${stem}.${format === 'midi' ? 'mid' : format}`;
};

export const phraseRecordingProject = (
  phrase: Phrase,
): Omit<RecordingProject, 'id'> => {
  const stepMs = 60000 / (phrase.bpm * STEPS_PER_BEAT);
  const settings: Omit<Melody, 'notes' | 'timbre' | 'octave'> = {
    title,
    scale: phrase.scale,
    mode: phrase.mode,
    customScale: phrase.customScale,
    pitch: phrase.pitch,
    bpm: phrase.bpm,
    timeSignature: phrase.timeSignature,
  };
  return {
    title,
    activeTrackId: 'melody',
    tracks: phraseParts(phrase)
      .filter(part => part.notes.length)
      .map(({ id, name, notes, timbre, octave }) => ({
        id,
        name,
        melody: {
          ...settings,
          timbre,
          octave,
          ...(timbre === 'drums'
            ? {
                scale: 'chromatic' as const,
                mode: 'chromatic' as const,
                pitch: 0,
                customScale: undefined,
              }
            : {}),
          notes: notes.map(({ midi, start, length }) => {
            const percussion = timbre === 'drums';
            const note = noteForMidi(midi + (percussion ? 12 : 0));
            const cents = percussion ? 0 : noteTuningCents(note, phrase);
            return {
              note,
              start: start * stepMs,
              duration: (start + length) * stepMs - start * stepMs,
              ...(cents
                ? {
                    expression: {
                      points: [
                        { position: 0, cents },
                        { position: 1, cents },
                      ],
                      techniques: [],
                    },
                  }
                : {}),
            };
          }),
        },
      })),
  };
};

export const phrasePlayback = (phrase: Phrase): PlaybackMelody => {
  const { tracks } = phraseRecordingProject(phrase);
  return {
    ...tracks[0].melody,
    notes: tracks.flatMap(({ melody }) =>
      melody.notes.map(note => ({ ...note, timbre: melody.timbre })),
    ),
  };
};

const tuneMidi = (bytes: Uint8Array, phrase: Phrase) => {
  const midi = parseMidi(bytes);
  midi.tracks = midi.tracks.map(events => {
    const program = events.find(event => event.type === 'programChange');
    if (!program || program.type !== 'programChange' || program.channel === 9)
      return events;
    // Independent tuning for simultaneous notes, with separate channels for each part.
    const available = Array.from(
      { length: 16 },
      (_, channel) => channel,
    ).filter(channel => channel !== 9 && channel % 3 === program.channel);
    const channels = new Map<number, number>();
    const tuned = events.map(event => {
      if (event.type !== 'noteOn' && event.type !== 'noteOff') return event;
      const cents = noteTuningCents(noteForMidi(event.noteNumber), phrase);
      if (!channels.has(cents)) channels.set(cents, available[channels.size]);
      return { ...event, channel: channels.get(cents)! };
    });
    return tuned.flatMap((event): MidiEvent[] => {
      if (event.type !== 'programChange') return [event];
      return Array.from(channels).flatMap(([cents, channel]): MidiEvent[] => [
        { ...event, channel },
        ...[
          [101, 0],
          [100, 0],
          [6, 2],
          [38, 0],
          [101, 127],
          [100, 127],
        ].map(
          ([controllerType, value]): MidiEvent => ({
            type: 'controller',
            deltaTime: 0,
            channel,
            controllerType,
            value,
          }),
        ),
        {
          type: 'pitchBend',
          deltaTime: 0,
          channel,
          value: Math.round((cents * 8192) / 200),
        },
      ]);
    });
  });
  return Uint8Array.from(writeMidi(midi));
};

export const encodePhraseMidi = (phrase: Phrase): Uint8Array => {
  const midi = new Midi();
  midi.header.name = title;
  midi.header.timeSignatures.push({
    ticks: 0,
    timeSignature: phrase.timeSignature.split('/').map(Number),
  });
  midi.header.setTempo(phrase.bpm);
  const stepTicks = midi.header.ppq / STEPS_PER_BEAT;
  phraseParts(phrase)
    .filter(part => part.notes.length)
    .forEach(({ name, notes, velocity, channel, timbre }) => {
      const track = midi.addTrack();
      track.name = name;
      track.channel = channel;
      track.instrument.number = timbre === 'drums' ? 0 : timbrePrograms[timbre];
      notes.forEach(note =>
        track.addNote({
          midi: note.midi,
          ticks: note.start * stepTicks,
          durationTicks: note.length * stepTicks,
          velocity,
        }),
      );
    });
  const bytes = midi.toArray();
  return isMicrotonalScale(phrase.scale) ? tuneMidi(bytes, phrase) : bytes;
};
