import { nanoid } from '@reduxjs/toolkit';
import { FormEvent, useEffect, useRef, useState } from 'react';
import styled from 'styled-components';

import {
  DrumBeat,
  MAX_BEAT_NAME_LENGTH,
  SavedDrumBeat,
  loadSavedDrumBeats,
  writeSavedDrumBeats,
} from 'app/services/DrumMachineService/beatLibrary';
import { tracksWithHits } from 'app/services/DrumMachineService/patterns';
import {
  CustomDrumSample,
  saveCustomSamples,
} from 'app/services/DrumMachineService/samples';
import { downloadBlob } from 'app/services/MelodyExportService';

interface Props {
  beat: DrumBeat;
  steps: number;
  busy: boolean;
  canLoad: boolean;
  onLoad: (beat: DrumBeat, samples?: CustomDrumSample[]) => void;
}

export const DrumBeatActions = ({
  beat,
  steps,
  busy,
  canLoad,
  onLoad,
}: Props) => {
  const [savedBeats, setSavedBeats] = useState(loadSavedDrumBeats);
  const [selectedId, setSelectedId] = useState('');
  const [name, setName] = useState('');
  const [transfer, setTransfer] = useState<'wav' | 'beat' | 'import'>();
  const [status, setStatus] = useState('');
  const [error, setError] = useState('');
  const fileInput = useRef<HTMLInputElement>(null);
  const mounted = useRef(true);
  const loadAvailable = useRef(canLoad);
  loadAvailable.current = canLoad;
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);
  const selected = savedBeats.find(item => item.id === selectedId);
  const hasHits = tracksWithHits(beat.state, steps).length > 0;

  const saveList = (next: SavedDrumBeat[]) => {
    setStatus('');
    setError('');
    try {
      writeSavedDrumBeats(next);
      setSavedBeats(next);
      return true;
    } catch {
      setError(
        'Could not save changes. Check your browser storage and try again.',
      );
      return false;
    }
  };

  const save = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const title = name.trim();
    if (!title || busy) return;
    const beats = loadSavedDrumBeats();
    if (beats.some(item => item.name.toLowerCase() === title.toLowerCase())) {
      setStatus('');
      setError('A beat with that name already exists. Choose another name.');
      return;
    }
    const next = { ...beat, id: nanoid(), name: title };
    if (saveList([next, ...beats])) {
      setName('');
      setSelectedId(next.id);
      setStatus(`Saved "${title}" in this browser.`);
    }
  };

  const remove = () => {
    if (
      !selected ||
      !window.confirm(`Delete "${selected.name}" from saved beats?`)
    )
      return;
    if (
      saveList(loadSavedDrumBeats().filter(item => item.id !== selected.id))
    ) {
      setSelectedId('');
      setStatus(`Deleted "${selected.name}".`);
    }
  };

  const download = async (kind: 'wav' | 'beat') => {
    setStatus('');
    setError('');
    setTransfer(kind);
    try {
      const filename = `drum-beat-${beat.bpm}-bpm`;
      if (kind === 'wav') {
        const { createDrumBeatWav } = await import(
          'app/services/DrumMachineService/export'
        );
        const wav = await createDrumBeatWav(
          { ...beat.state, bpm: beat.bpm, steps },
          beat.effects,
        );
        downloadBlob(wav, `${filename}.wav`);
      } else {
        const { createBeatFile } = await import(
          'app/services/DrumMachineService/beatFile'
        );
        downloadBlob(await createBeatFile(beat), `${filename}.json`);
      }
      setStatus(
        kind === 'wav'
          ? 'WAV download started.'
          : 'Beat file download started.',
      );
    } catch (cause) {
      setError(
        cause instanceof Error
          ? `Could not download the beat. ${cause.message}`
          : 'Could not download the beat. Try again.',
      );
    } finally {
      setTransfer(undefined);
    }
  };

  const importBeat = async (file: File) => {
    setStatus('');
    setError('');
    setTransfer('import');
    const checkAvailability = () => {
      if (!loadAvailable.current)
        throw new Error(
          'Stop recording or finish importing the sample, then try again.',
        );
      return mounted.current;
    };
    try {
      const { readBeatFile } = await import(
        'app/services/DrumMachineService/beatFile'
      );
      const imported = await readBeatFile(file);
      if (!checkAvailability()) return;
      await saveCustomSamples(imported.clips);
      if (!checkAvailability()) return;
      onLoad(
        imported.beat,
        imported.clips.map(({ sample }) => sample),
      );
      setSelectedId('');
      setStatus('Beat imported. Give it a name to save it in this browser.');
    } catch (cause) {
      if (mounted.current)
        setError(
          cause instanceof Error
            ? `Could not import the beat. ${cause.message}`
            : 'Could not import the beat. Try again.',
        );
    } finally {
      if (mounted.current) setTransfer(undefined);
    }
  };

  return (
    <Section aria-label="Save and download beats">
      <Actions as="form" onSubmit={save}>
        <label>
          Beat name
          <input
            type="text"
            value={name}
            maxLength={MAX_BEAT_NAME_LENGTH}
            onChange={event => setName(event.target.value)}
          />
        </label>
        <button
          type="submit"
          disabled={busy || transfer === 'import' || !name.trim()}
        >
          Save beat
        </button>
      </Actions>
      {savedBeats.length > 0 && (
        <Actions>
          <label>
            Saved beats
            <select
              value={selectedId}
              onChange={event => setSelectedId(event.target.value)}
            >
              <option value="" disabled>
                Choose a beat
              </option>
              {savedBeats.map(item => (
                <option key={item.id} value={item.id}>
                  {item.name} ({item.bpm} BPM, {item.timeSignature})
                </option>
              ))}
            </select>
          </label>
          <button
            type="button"
            disabled={!canLoad || !selected || transfer === 'import'}
            onClick={() => {
              if (!selected) return;
              onLoad(selected);
              setError('');
              setStatus(`Loaded "${selected.name}".`);
            }}
          >
            Load beat
          </button>
          <button type="button" disabled={!selected} onClick={remove}>
            Delete saved beat
          </button>
        </Actions>
      )}
      <Actions>
        <button
          type="button"
          disabled={busy || !hasHits || !!transfer}
          onClick={() => void download('wav')}
        >
          {transfer === 'wav' ? 'Preparing WAV…' : 'Download WAV'}
        </button>
        <button
          type="button"
          disabled={busy || !!transfer}
          onClick={() => void download('beat')}
        >
          {transfer === 'beat' ? 'Preparing beat file…' : 'Download beat file'}
        </button>
        <button
          type="button"
          disabled={!canLoad || !!transfer}
          onClick={() => fileInput.current?.click()}
        >
          {transfer === 'import' ? 'Importing beat…' : 'Import beat'}
        </button>
        <input
          ref={fileInput}
          type="file"
          hidden
          accept=".json,application/json"
          aria-label="Beat file"
          onChange={event => {
            const file = event.target.files?.[0];
            event.target.value = '';
            if (file && canLoad && !transfer) void importBeat(file);
          }}
        />
      </Actions>
      <Message>
        {hasHits
          ? 'WAV includes one bar and any sound that rings out after it.'
          : 'Add a hit to an unmuted row to download a WAV.'}{' '}
        Use a beat file to open the editable beat in Drum Machine.
      </Message>
      {status && <Message role="status">{status}</Message>}
      {error && <Message role="alert">{error}</Message>}
    </Section>
  );
};

const Section = styled.section`
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid ${p => p.theme.border};
`;

const Actions = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin: 0 0 8px;
  font-size: 12px;

  label {
    display: flex;
    align-items: center;
    gap: 8px;
    max-width: 100%;
  }

  input,
  select {
    min-width: 0;
    width: 170px;
    font: inherit;
  }

  input {
    min-height: 40px;
    padding: 8px 12px;
    border: 1px solid ${p => p.theme.border};
    border-radius: 8px;
    color: ${p => p.theme.text};
    background: ${p => p.theme.surface};
    font-size: 16px;
  }
`;

const Message = styled.p`
  margin: 6px 0 0;
  color: ${p => p.theme.textSecondary};
  font-size: 12px;
`;
