import {
  chordQualities,
  chordSymbol,
  formatPitch,
  pitchClass,
  spellPitch,
} from 'app/services/ChordsService';
import type { ChordQuality } from 'app/services/ChordsService';
import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import {
  microtonalPreset,
  tuningLabel,
} from 'app/services/SettingsService/microtonal';
import { getScale } from 'app/services/SettingsService/scales';

import type { GenerationSettings } from './options';

const triadQualities = (Object.keys(chordQualities) as ChordQuality[]).filter(
  quality => chordQualities[quality].intervals.length === 3,
);

export const phraseHarmony = ({
  tonic,
  scale,
  mode,
  customScale,
}: GenerationSettings) => {
  const pitch = pitchClass(tonic);
  const offsets = getScale(scale, mode, customScale).map(pitchClass);
  const size = offsets.length;
  const cents = microtonalPreset(scale, mode)?.cents;
  const flavor =
    offsets.includes(3) && !offsets.includes(4) ? 'minor' : 'major';
  const semitone = (step: number) =>
    offsets[step % size] + 12 * Math.floor(step / size);
  const midiFor = (step: number) => 60 + pitch + semitone(step);
  const reference = getScale(
    'diatonic',
    flavor === 'minor' ? 'aeolian' : 'ionian',
  ).map(pitchClass);
  const degreeFor = (degree: number) =>
    size === 7
      ? degree
      : offsets.reduce(
          (best, offset, index) =>
            Math.abs(offset - reference[degree]) <
            Math.abs(offsets[best] - reference[degree])
              ? index
              : best,
          0,
        );

  const chordAt = (root: number) => {
    const interval = (step: number) => semitone(step) - semitone(root);
    const candidates = Array.from({ length: size - 1 }, (_, i) => root + i + 1);
    let steps = [root, root + 2, root + 4];
    if (size < 3) steps = [root, ...candidates];
    else if (size !== 7) {
      const closest = (available: number[], target: number) =>
        available.reduce((best, step) =>
          Math.abs(interval(step) - target) < Math.abs(interval(best) - target)
            ? step
            : best,
        );
      const fifth = closest(candidates, 7);
      const third = closest(
        candidates.filter(step => step !== fifth),
        flavor === 'minor' ? 3 : 4,
      );
      steps = [root, Math.min(third, fifth), Math.max(third, fifth)];
    }

    const noteName = (step: number) =>
      size === 7
        ? spellPitch(tonic, semitone(step), step)
        : chromaticNotes[midiFor(step) % 12];
    const quality =
      !cents &&
      steps.length === 3 &&
      triadQualities.find(candidate => {
        const intervals: readonly number[] =
          chordQualities[candidate].intervals;
        return intervals.every((value, i) => value === interval(steps[i]));
      });
    const label = quality
      ? chordSymbol({ root: noteName(root), quality })
      : steps
          .map(step => {
            const index = step % size;
            const adjustment = cents ? cents[index] - offsets[index] * 100 : 0;
            return `${formatPitch(noteName(step))}${
              adjustment ? tuningLabel(adjustment) : ''
            }`;
          })
          .join(' · ');
    return { steps, label };
  };

  return { pitch, size, flavor, midiFor, degreeFor, chordAt } as const;
};
