import { useId, useLayoutEffect, useRef } from 'react';
import { useSelector } from 'react-redux';
import styled from 'styled-components';

import {
  EffectPreset,
  builtInEffectPresets,
  canAddPresetPedal,
  togglePresetPedal,
} from 'app/services/EffectsService/presets';
import { selectEffects } from 'app/services/EffectsService/selectors';
import { InstrumentEffects } from 'app/services/EffectsService/settings';
import { guitarOverdrive } from 'app/services/VirtualGuitarService/sound';

import { EffectPedalCard } from 'app/components/EffectPedalCard';
import type { EffectsDialogElement } from 'app/components/EffectsDialog';
import { PedalCatalogDialog } from 'app/components/PedalCatalogDialog';

export const GuitarPedals = ({
  settings,
  onChange,
}: {
  settings: InstrumentEffects;
  onChange: (settings: InstrumentEffects) => void;
}) => {
  const { customPresets = [] } = useSelector(selectEffects);
  const pedals = settings.pedals ?? [];
  const available = (preset: EffectPreset) =>
    !pedals.some(pedal => pedal.presetId === preset.id) &&
    canAddPresetPedal(settings, preset);
  const presets = [
    guitarOverdrive,
    ...builtInEffectPresets,
    ...customPresets,
  ].filter(preset => preset.id !== 'clean' && available(preset));
  const chain = useRef<HTMLUListElement>(null);
  const added = useRef(false);
  const addPedal = useRef<HTMLButtonElement>(null);
  const catalog = useRef<EffectsDialogElement>(null);
  const catalogId = useId();

  useLayoutEffect(() => {
    if (added.current && chain.current) {
      chain.current.scrollLeft = chain.current.scrollWidth;
      added.current = false;
    }
  }, [pedals.length]);

  return (
    <Pedalboard role="group" aria-label="Effects pedals">
      {pedals.length > 0 && (
        <Chain ref={chain} aria-label="Pedal order">
          {pedals.map(pedal => (
            <Slot key={pedal.id}>
              <EffectPedalCard
                compact
                id={pedal.presetId}
                name={pedal.name}
                description={pedal.name}
                active={pedal.enabled}
                pressed={pedal.enabled}
                action={pedal.name}
                onToggle={() =>
                  onChange({
                    ...settings,
                    pedals: pedals.map(item =>
                      item.id === pedal.id
                        ? { ...item, enabled: !item.enabled }
                        : item,
                    ),
                  })
                }
              />
              <Remove
                type="button"
                aria-label={`Remove ${pedal.name}`}
                title={`Remove ${pedal.name}`}
                onClick={() => {
                  onChange({
                    ...settings,
                    pedals: pedals.filter(item => item.id !== pedal.id),
                  });
                  addPedal.current?.focus();
                }}
              >
                <span aria-hidden="true">×</span>
              </Remove>
            </Slot>
          ))}
        </Chain>
      )}
      <Add
        ref={addPedal}
        type="button"
        disabled={!presets.length}
        aria-haspopup="dialog"
        aria-controls={catalogId}
        onClick={() => {
          catalog.current?.showModal();
          catalog.current?.querySelector('input')?.focus();
        }}
      >
        <span aria-hidden="true">+</span>
        {presets.length ? 'Add pedal' : 'Board full'}
      </Add>
      <PedalCatalogDialog
        id={catalogId}
        dialog={catalog}
        settings={settings}
        presets={presets}
        onClose={() => addPedal.current?.focus()}
        onSelect={preset => {
          added.current = true;
          onChange(togglePresetPedal(settings, preset));
          catalog.current?.close();
        }}
      />
    </Pedalboard>
  );
};

const Pedalboard = styled.div`
  display: flex;
  align-items: stretch;
  gap: clamp(6px, 1vw, 16px);
  min-width: 0;
  min-height: 0;
  --pedal-width: clamp(74px, calc(var(--gear-size) * 0.85), 190px);

  @supports (width: 1cqh) {
    --pedal-width: clamp(74px, 58cqh, 216px);
  }

  @media (max-height: 470px) {
    --pedal-width: 100px;
  }
`;

const Chain = styled.ul`
  display: flex;
  align-self: stretch;
  gap: clamp(10px, 1vw, 16px);
  min-width: 0;
  margin: 0;
  padding: 4px 6px;
  overflow: auto hidden;
  overscroll-behavior-x: contain;
  list-style: none;
`;

const Slot = styled.li`
  position: relative;
  flex: 0 0 var(--pedal-width);
  > button:first-child {
    padding-top: 20px;
  }

  @media (max-height: 470px) {
    > button:first-child {
      padding-inline: 3px;
      padding-top: 14px;
    }
  }
`;

const Remove = styled.button`
  position: absolute;
  z-index: 1;
  top: 0;
  right: -4px;
  display: grid;
  place-items: start end;
  width: 40px;
  height: 40px;
  padding: 0;
  border: 0;
  background: transparent;

  span {
    display: grid;
    place-items: center;
    width: 23px;
    height: 23px;
    border: 1px solid ${p => p.theme.border};
    border-radius: 50%;
    background: ${p => p.theme.surface};
    font-size: 17px;
    line-height: 1;
  }

  &:hover span {
    border-color: ${p => p.theme.primary};
  }
`;

const Add = styled.button`
  position: relative;
  display: grid;
  align-content: center;
  justify-items: center;
  flex: 0 0 var(--pedal-width);
  min-height: 0;
  padding: 6px 4px;
  background: transparent;
  border: 1px dashed ${p => p.theme.border};
  border-radius: 12px;
  color: ${p => p.theme.textSecondary};
  font-size: clamp(11px, 1.4vw, 14px);
  font-weight: 600;

  span {
    color: ${p => p.theme.primary};
    font-size: 26px;
    line-height: 1.15;
  }

  &:hover,
  &:focus-visible {
    border-color: ${p => p.theme.primary};
    color: ${p => p.theme.text};
  }
`;
