import { DrumSample, isDrumSample } from './samples';

export const DRUM_TRACKS = [
  { id: 'kick', label: 'Kick', note: 36 },
  { id: 'snare', label: 'Snare', note: 38 },
  { id: 'closedHat', label: 'Closed hi-hat', note: 42 },
  { id: 'openHat', label: 'Open hi-hat', note: 46 },
  { id: 'clap', label: 'Clap', note: 39 },
  { id: 'tom', label: 'Tom', note: 45 },
] as const;

export type DrumTrack = string;
export type DrumPattern = Record<DrumTrack, boolean[]>;
export type MutedTracks = Record<DrumTrack, boolean>;
export interface DrumMachineState {
  tracks: DrumTrack[];
  pattern: DrumPattern;
  muted: MutedTracks;
  samples: Record<DrumTrack, DrumSample>;
  volume: number;
  preset: string;
}

export const STORAGE_KEY = 'qwertophone.drum-machine.v1';
export const MAX_STEPS = 24;
const DEFAULT_TRACKS = DRUM_TRACKS.slice(0, 4).map(({ id }) => id);

export const getDrumTrackLabel = (id: DrumTrack, index: number) =>
  DRUM_TRACKS.find(track => track.id === id)?.label ?? `Row ${index + 1}`;

export const defaultDrumSample = (id: DrumTrack): DrumSample => ({
  kind: 'builtin',
  note: DRUM_TRACKS.find(track => track.id === id)?.note ?? 36,
});

const isDrumTrack = (value: unknown): value is DrumTrack =>
  typeof value === 'string' &&
  (DRUM_TRACKS.some(({ id }) => id === value) || /^track:[\w-]+$/.test(value));

const pattern = (hits: Partial<Record<DrumTrack, number[]>>): DrumPattern =>
  Object.fromEntries(
    DRUM_TRACKS.map(({ id }) => [
      id,
      Array.from({ length: MAX_STEPS }, (_, i) => !!hits[id]?.includes(i)),
    ]),
  ) as DrumPattern;

export const DRUM_PRESETS = [
  {
    id: 'basic',
    label: 'Basic beat',
    pattern: pattern({
      kick: [0, 8],
      snare: [4, 12],
      closedHat: [0, 2, 4, 6, 8, 10, 12, 14],
    }),
  },
  {
    id: 'house',
    label: 'House',
    pattern: pattern({
      kick: [0, 4, 8, 12],
      clap: [4, 12],
      closedHat: [0, 4, 8, 12],
      openHat: [2, 6, 10, 14],
    }),
  },
  {
    id: 'breakbeat',
    label: 'Breakbeat',
    pattern: pattern({
      kick: [0, 6, 10],
      snare: [4, 12],
      closedHat: [0, 2, 4, 6, 8, 10, 12],
      openHat: [14],
      tom: [15],
    }),
  },
];

export const emptyPattern = (
  tracks: DrumTrack[] = DEFAULT_TRACKS,
): DrumPattern =>
  Object.fromEntries(tracks.map(id => [id, Array(MAX_STEPS).fill(false)]));
export const unmutedTracks = (
  tracks: DrumTrack[] = DEFAULT_TRACKS,
): MutedTracks => Object.fromEntries(tracks.map(id => [id, false]));

export const defaultDrumState = (
  tracks: DrumTrack[] = DEFAULT_TRACKS,
): DrumMachineState => ({
  tracks: [...tracks],
  pattern: Object.fromEntries(
    tracks.map(id => [
      id,
      [...(DRUM_PRESETS[0].pattern[id] ?? Array(MAX_STEPS).fill(false))],
    ]),
  ),
  muted: unmutedTracks(tracks),
  samples: Object.fromEntries(tracks.map(id => [id, defaultDrumSample(id)])),
  volume: 0.7,
  preset: DRUM_PRESETS[0].id,
});

export const normalizeDrumState = (value: unknown): DrumMachineState => {
  if (!value || typeof value !== 'object') return defaultDrumState();
  const saved = value as Partial<DrumMachineState>;
  // Saves predating row controls always contained the original six tracks.
  const tracks = Array.isArray(saved.tracks)
    ? Array.from(new Set<DrumTrack>(saved.tracks.filter(isDrumTrack)))
    : saved.tracks === undefined
    ? DRUM_TRACKS.map(({ id }) => id)
    : DEFAULT_TRACKS;
  const defaults = defaultDrumState(
    Array.isArray(saved.tracks) && saved.tracks.length && !tracks.length
      ? DEFAULT_TRACKS
      : tracks,
  );
  defaults.tracks.forEach(id => {
    const row = saved.pattern?.[id];
    if (Array.isArray(row)) {
      defaults.pattern[id] = Array.from(
        { length: MAX_STEPS },
        (_, i) => row[i] === true,
      );
    }
    defaults.muted[id] = saved.muted?.[id] === true;
    const sample = saved.samples?.[id];
    if (isDrumSample(sample)) {
      defaults.samples[id] = sample;
    }
  });
  if (typeof saved.volume === 'number' && Number.isFinite(saved.volume)) {
    defaults.volume = Math.max(0, Math.min(1, saved.volume));
  }
  defaults.preset =
    DRUM_PRESETS.find(
      preset =>
        preset.id === saved.preset &&
        Array.from(
          new Set([...Object.keys(preset.pattern), ...defaults.tracks]),
        ).every(id =>
          Array.from({ length: MAX_STEPS }).every(
            (_, i) =>
              (preset.pattern[id]?.[i] ?? false) ===
              (defaults.pattern[id]?.[i] ?? false),
          ),
        ),
    )?.id ?? 'custom';
  return defaults;
};

export const loadDrumState = (): DrumMachineState => {
  try {
    return normalizeDrumState(
      JSON.parse(
        localStorage.getItem(STORAGE_KEY) ??
          localStorage.getItem('quartet.drum-machine.v1') ??
          'null',
      ),
    );
  } catch {
    return defaultDrumState();
  }
};

export const tracksWithHits = (state: DrumMachineState, steps: number) =>
  state.tracks.filter(
    id => !state.muted[id] && state.pattern[id].slice(0, steps).some(Boolean),
  );

export const saveDrumState = (state: DrumMachineState) => {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  } catch {
    // Playback remains available when browser storage is full or disabled.
  }
};
